export interface Env {
  Variables?: Record<string, unknown>;
}
export interface Ctx<E extends Env = Env> {
  path: string;
  token: string;
  log: string[];
  env?: E;
}
export type Middleware<E extends Env = any> = (ctx: Ctx<E>, next: () => Promise<void>) => Promise<void>;
export interface GuardOptions {
  token: string;
}
export declare const guard: <E extends Env = Env>(options: GuardOptions) => Middleware<E>;
export declare class Router<E extends Env = Env> {
  on<E2 extends Env = E>(path: string, ...handlers: Middleware<E2>[]): this;
  dispatch(path: string, token: string): Promise<string[]>;
}
